  final String propertyId;
  final String token;
  final String role;
  final String? email;

  /// null = open link
  final String? shareMode;

  /// for guest links
  final String? expiresAt;
  final int? maxUses;
  final int useCount;
  final String? revokedAt;
  final String createdBy;
  final String createdAt;
  const Invite({
    required this.id,
    required this.propertyId,
    required this.token,
    required this.role,
    this.email,
    this.shareMode,
    this.expiresAt,
    this.maxUses,
    required this.useCount,
    this.revokedAt,
    required this.createdBy,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['property_id'] = Variable<String>(propertyId);
    map['token'] = Variable<String>(token);
    map['role'] = Variable<String>(role);
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    if (!nullToAbsent || shareMode != null) {
      map['share_mode'] = Variable<String>(shareMode);
    }
    if (!nullToAbsent || expiresAt != null) {
      map['expires_at'] = Variable<String>(expiresAt);
    }
    if (!nullToAbsent || maxUses != null) {
      map['max_uses'] = Variable<int>(maxUses);
    }
    map['use_count'] = Variable<int>(useCount);
    if (!nullToAbsent || revokedAt != null) {
      map['revoked_at'] = Variable<String>(revokedAt);
    }
    map['created_by'] = Variable<String>(createdBy);
    map['created_at'] = Variable<String>(createdAt);
    return map;
  }

  InvitesCompanion toCompanion(bool nullToAbsent) {
    return InvitesCompanion(
      id: Value(id),
      propertyId: Value(propertyId),
      token: Value(token),
      role: Value(role),
      email: email == null && nullToAbsent
          ? const Value.absent()
          : Value(email),
      shareMode: shareMode == null && nullToAbsent
          ? const Value.absent()
          : Value(shareMode),
      expiresAt: expiresAt == null && nullToAbsent
          ? const Value.absent()
          : Value(expiresAt),
      maxUses: maxUses == null && nullToAbsent
          ? const Value.absent()
          : Value(maxUses),
      useCount: Value(useCount),
      revokedAt: revokedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(revokedAt),
      createdBy: Value(createdBy),
      createdAt: Value(createdAt),
    );
  }

  factory Invite.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Invite(
      id: serializer.fromJson<String>(json['id']),
      propertyId: serializer.fromJson<String>(json['property_id']),
      token: serializer.fromJson<String>(json['token']),
      role: serializer.fromJson<String>(json['role']),
      email: serializer.fromJson<String?>(json['email']),
      shareMode: serializer.fromJson<String?>(json['share_mode']),
      expiresAt: serializer.fromJson<String?>(json['expires_at']),
      maxUses: serializer.fromJson<int?>(json['max_uses']),
      useCount: serializer.fromJson<int>(json['use_count']),
      revokedAt: serializer.fromJson<String?>(json['revoked_at']),
      createdBy: serializer.fromJson<String>(json['created_by']),
      createdAt: serializer.fromJson<String>(json['created_at']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'property_id': serializer.toJson<String>(propertyId),
      'token': serializer.toJson<String>(token),
      'role': serializer.toJson<String>(role),
      'email': serializer.toJson<String?>(email),
      'share_mode': serializer.toJson<String?>(shareMode),
      'expires_at': serializer.toJson<String?>(expiresAt),
      'max_uses': serializer.toJson<int?>(maxUses),
      'use_count': serializer.toJson<int>(useCount),
      'revoked_at': serializer.toJson<String?>(revokedAt),
      'created_by': serializer.toJson<String>(createdBy),
      'created_at': serializer.toJson<String>(createdAt),
    };
  }

  Invite copyWith({
    String? id,
    String? propertyId,
    String? token,
    String? role,
    Value<String?> email = const Value.absent(),
    Value<String?> shareMode = const Value.absent(),
    Value<String?> expiresAt = const Value.absent(),
    Value<int?> maxUses = const Value.absent(),
    int? useCount,
    Value<String?> revokedAt = const Value.absent(),
    String? createdBy,
    String? createdAt,
  }) => Invite(
    id: id ?? this.id,
    propertyId: propertyId ?? this.propertyId,
    token: token ?? this.token,
    role: role ?? this.role,
    email: email.present ? email.value : this.email,
    shareMode: shareMode.present ? shareMode.value : this.shareMode,
    expiresAt: expiresAt.present ? expiresAt.value : this.expiresAt,
    maxUses: maxUses.present ? maxUses.value : this.maxUses,
    useCount: useCount ?? this.useCount,
    revokedAt: revokedAt.present ? revokedAt.value : this.revokedAt,
    createdBy: createdBy ?? this.createdBy,
    createdAt: createdAt ?? this.createdAt,
  );
  Invite copyWithCompanion(InvitesCompanion data) {
    return Invite(
      id: data.id.present ? data.id.value : this.id,
      propertyId: data.propertyId.present
          ? data.propertyId.value
          : this.propertyId,
      token: data.token.present ? data.token.value : this.token,
      role: data.role.present ? data.role.value : this.role,
      email: data.email.present ? data.email.value : this.email,
      shareMode: data.shareMode.present ? data.shareMode.value : this.shareMode,
      expiresAt: data.expiresAt.present ? data.expiresAt.value : this.expiresAt,
      maxUses: data.maxUses.present ? data.maxUses.value : this.maxUses,
      useCount: data.useCount.present ? data.useCount.value : this.useCount,
      revokedAt: data.revokedAt.present ? data.revokedAt.value : this.revokedAt,
      createdBy: data.createdBy.present ? data.createdBy.value : this.createdBy,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Invite(')
          ..write('id: $id, ')
          ..write('propertyId: $propertyId, ')
          ..write('token: $token, ')
          ..write('role: $role, ')
          ..write('email: $email, ')
          ..write('shareMode: $shareMode, ')
          ..write('expiresAt: $expiresAt, ')
          ..write('maxUses: $maxUses, ')
          ..write('useCount: $useCount, ')
          ..write('revokedAt: $revokedAt, ')
          ..write('createdBy: $createdBy, ')
          ..write('createdAt: $createdAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    propertyId,
    token,
    role,
    email,
    shareMode,
    expiresAt,
    maxUses,
    useCount,
    revokedAt,
    createdBy,
    createdAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Invite &&
          other.id == this.id &&
          other.propertyId == this.propertyId &&
          other.token == this.token &&
          other.role == this.role &&
          other.email == this.email &&
          other.shareMode == this.shareMode &&
          other.expiresAt == this.expiresAt &&
          other.maxUses == this.maxUses &&
          other.useCount == this.useCount &&
          other.revokedAt == this.revokedAt &&
          other.createdBy == this.createdBy &&
          other.createdAt == this.createdAt);
}

