      token: token ?? this.token,
      role: role ?? this.role,
      email: email ?? this.email,
      shareMode: shareMode ?? this.shareMode,
      expiresAt: expiresAt ?? this.expiresAt,
      maxUses: maxUses ?? this.maxUses,
