class Feature extends DataClass implements Insertable<Feature> {
  final String id;
  final String propertyId;
  final String? zoneId;
  final String featureTypeId;
  final String? name;
  final String geojson;

  /// Point, LineString, or Polygon
  final double? lat;
  final double? lng;

  /// centroid, denormalized
  final String? installedOn;

  /// for infrastructure
  final String? retiredOn;
  final String? currentCondition;
  final String? attributesJson;

  /// type-specific: flow_rate_gpm, capacity_gal...
  final String? notes;
  final String createdBy;
  final String createdAt;
  final String updatedAt;
  final String? deletedAt;
  const Feature({
    required this.id,
    required this.propertyId,
    this.zoneId,
    required this.featureTypeId,
    this.name,
    required this.geojson,
    this.lat,
    this.lng,
    this.installedOn,
    this.retiredOn,
    this.currentCondition,
    this.attributesJson,
    this.notes,
    required this.createdBy,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['property_id'] = Variable<String>(propertyId);
    if (!nullToAbsent || zoneId != null) {
      map['zone_id'] = Variable<String>(zoneId);
    }
    map['feature_type_id'] = Variable<String>(featureTypeId);
    if (!nullToAbsent || name != null) {
      map['name'] = Variable<String>(name);
    }
    map['geojson'] = Variable<String>(geojson);
    if (!nullToAbsent || lat != null) {
      map['lat'] = Variable<double>(lat);
    }
    if (!nullToAbsent || lng != null) {
      map['lng'] = Variable<double>(lng);
    }
    if (!nullToAbsent || installedOn != null) {
      map['installed_on'] = Variable<String>(installedOn);
    }
    if (!nullToAbsent || retiredOn != null) {
      map['retired_on'] = Variable<String>(retiredOn);
    }
    if (!nullToAbsent || currentCondition != null) {
      map['current_condition'] = Variable<String>(currentCondition);
    }
    if (!nullToAbsent || attributesJson != null) {
      map['attributes_json'] = Variable<String>(attributesJson);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_by'] = Variable<String>(createdBy);
    map['created_at'] = Variable<String>(createdAt);
    map['updated_at'] = Variable<String>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<String>(deletedAt);
    }
    return map;
  }

  FeaturesCompanion toCompanion(bool nullToAbsent) {
    return FeaturesCompanion(
