      map['usda_plants_symbol'] = Variable<String>(usdaPlantsSymbol.value);
    }
    if (itisTsn.present) {
      map['itis_tsn'] = Variable<String>(itisTsn.value);
    }
    if (notes.present) {
      map['notes'] = Variable<String>(notes.value);
    }
    if (isFavorite.present) {
      map['is_favorite'] = Variable<int>(isFavorite.value);
    }
    if (createdBy.present) {
      map['created_by'] = Variable<String>(createdBy.value);
    }
    if (createdAt.present) {
      map['created_at'] = Variable<String>(createdAt.value);
    }
    if (updatedAt.present) {
      map['updated_at'] = Variable<String>(updatedAt.value);
    }
    if (deletedAt.present) {
      map['deleted_at'] = Variable<String>(deletedAt.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('TaxaCompanion(')
          ..write('id: $id, ')
          ..write('propertyId: $propertyId, ')
          ..write('scientificName: $scientificName, ')
          ..write('commonName: $commonName, ')
          ..write('family: $family, ')
          ..write('rank: $rank, ')
          ..write('growthForm: $growthForm, ')
          ..write('nativity: $nativity, ')
          ..write('gbifKey: $gbifKey, ')
          ..write('inatTaxonId: $inatTaxonId, ')
          ..write('usdaPlantsSymbol: $usdaPlantsSymbol, ')
          ..write('itisTsn: $itisTsn, ')
          ..write('notes: $notes, ')
          ..write('isFavorite: $isFavorite, ')
          ..write('createdBy: $createdBy, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('deletedAt: $deletedAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

