class EnvContext extends DataClass implements Insertable<EnvContext> {
  final String id;
  final String propertyId;
  final double lat;
  final double lng;
  final String resolvedFor;

  /// date this context describes
  final double? tempC;
  final double? tempMinC;
  final double? tempMaxC;
  final double? precip24hMm;
  final double? precip7dMm;
  final double? precip30dMm;
  final double? precip90dMm;
  final int? daysSinceRain;
  final double? gddBase10Ytd;
  final String? soilMukey;
  final String? soilSeries;
  final String? soilTexture;
  final String? soilDrainageClass;
  final double? soilPh;
  final String? sourceJson;
  final String? fetchedAt;
  final int isStale;

  /// created offline, needs backfill
  final String createdAt;
  final String updatedAt;
  const EnvContext({
    required this.id,
    required this.propertyId,
    required this.lat,
    required this.lng,
    required this.resolvedFor,
    this.tempC,
    this.tempMinC,
    this.tempMaxC,
    this.precip24hMm,
    this.precip7dMm,
    this.precip30dMm,
    this.precip90dMm,
    this.daysSinceRain,
    this.gddBase10Ytd,
    this.soilMukey,
    this.soilSeries,
    this.soilTexture,
    this.soilDrainageClass,
    this.soilPh,
    this.sourceJson,
    this.fetchedAt,
    required this.isStale,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['property_id'] = Variable<String>(propertyId);
    map['lat'] = Variable<double>(lat);
    map['lng'] = Variable<double>(lng);
    map['resolved_for'] = Variable<String>(resolvedFor);
    if (!nullToAbsent || tempC != null) {
      map['temp_c'] = Variable<double>(tempC);
    }
    if (!nullToAbsent || tempMinC != null) {
      map['temp_min_c'] = Variable<double>(tempMinC);
    }
    if (!nullToAbsent || tempMaxC != null) {
      map['temp_max_c'] = Variable<double>(tempMaxC);
    }
    if (!nullToAbsent || precip24hMm != null) {
      map['precip_24h_mm'] = Variable<double>(precip24hMm);
    }
    if (!nullToAbsent || precip7dMm != null) {
      map['precip_7d_mm'] = Variable<double>(precip7dMm);
    }
    if (!nullToAbsent || precip30dMm != null) {
      map['precip_30d_mm'] = Variable<double>(precip30dMm);
    }
    if (!nullToAbsent || precip90dMm != null) {
      map['precip_90d_mm'] = Variable<double>(precip90dMm);
    }
    if (!nullToAbsent || daysSinceRain != null) {
      map['days_since_rain'] = Variable<int>(daysSinceRain);
    }
    if (!nullToAbsent || gddBase10Ytd != null) {
      map['gdd_base10_ytd'] = Variable<double>(gddBase10Ytd);
    }
    if (!nullToAbsent || soilMukey != null) {
      map['soil_mukey'] = Variable<String>(soilMukey);
    }
    if (!nullToAbsent || soilSeries != null) {
      map['soil_series'] = Variable<String>(soilSeries);
    }
    if (!nullToAbsent || soilTexture != null) {
      map['soil_texture'] = Variable<String>(soilTexture);
    }
    if (!nullToAbsent || soilDrainageClass != null) {
      map['soil_drainage_class'] = Variable<String>(soilDrainageClass);
    }
    if (!nullToAbsent || soilPh != null) {
      map['soil_ph'] = Variable<double>(soilPh);
    }
    if (!nullToAbsent || sourceJson != null) {
      map['source_json'] = Variable<String>(sourceJson);
    }
    if (!nullToAbsent || fetchedAt != null) {
      map['fetched_at'] = Variable<String>(fetchedAt);
    }
    map['is_stale'] = Variable<int>(isStale);
    map['created_at'] = Variable<String>(createdAt);
    map['updated_at'] = Variable<String>(updatedAt);
    return map;
  }

  EnvContextsCompanion toCompanion(bool nullToAbsent) {
    return EnvContextsCompanion(
      id: Value(id),
      propertyId: Value(propertyId),
      lat: Value(lat),
      lng: Value(lng),
      resolvedFor: Value(resolvedFor),
      tempC: tempC == null && nullToAbsent
          ? const Value.absent()
          : Value(tempC),
      tempMinC: tempMinC == null && nullToAbsent
          ? const Value.absent()
          : Value(tempMinC),
      tempMaxC: tempMaxC == null && nullToAbsent
