    }
    if (createdAt.present) {
      map['created_at'] = Variable<String>(createdAt.value);
    }
    if (updatedAt.present) {
      map['updated_at'] = Variable<String>(updatedAt.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('EnvContextsCompanion(')
          ..write('id: $id, ')
          ..write('propertyId: $propertyId, ')
          ..write('lat: $lat, ')
          ..write('lng: $lng, ')
          ..write('resolvedFor: $resolvedFor, ')
          ..write('tempC: $tempC, ')
          ..write('tempMinC: $tempMinC, ')
          ..write('tempMaxC: $tempMaxC, ')
          ..write('precip24hMm: $precip24hMm, ')
          ..write('precip7dMm: $precip7dMm, ')
          ..write('precip30dMm: $precip30dMm, ')
          ..write('precip90dMm: $precip90dMm, ')
          ..write('daysSinceRain: $daysSinceRain, ')
          ..write('gddBase10Ytd: $gddBase10Ytd, ')
          ..write('soilMukey: $soilMukey, ')
          ..write('soilSeries: $soilSeries, ')
          ..write('soilTexture: $soilTexture, ')
          ..write('soilDrainageClass: $soilDrainageClass, ')
          ..write('soilPh: $soilPh, ')
          ..write('sourceJson: $sourceJson, ')
          ..write('fetchedAt: $fetchedAt, ')
          ..write('isStale: $isStale, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

