class Observation extends DataClass implements Insertable<Observation> {
  final String id;
  final String propertyId;
  final String? zoneId;

  /// auto-assigned by point-in-polygon
  final String? featureId;

  /// optional: observed at/about a feature
  final String observedAt;
  final String localTz;
  final double lat;
  final double lng;
  final double? gpsAccuracyM;
  final double? altitudeM;
  final double? headingDeg;
  final String observationType;
  final String? taxonId;
  final String? taxonConfidence;
  final int? countEstimate;
  final String? phenology;
  final int isSuggestion;

  /// naturalist-role submissions
  final String? acceptedAt;
  final String? acceptedBy;
  final String? notes;
  final String? envContextId;
  final String createdBy;
  final String createdAt;
  final String updatedAt;
  final String? deletedAt;
  const Observation({
    required this.id,
    required this.propertyId,
    this.zoneId,
    this.featureId,
    required this.observedAt,
    required this.localTz,
    required this.lat,
    required this.lng,
    this.gpsAccuracyM,
    this.altitudeM,
    this.headingDeg,
    required this.observationType,
    this.taxonId,
    this.taxonConfidence,
    this.countEstimate,
    this.phenology,
    required this.isSuggestion,
    this.acceptedAt,
    this.acceptedBy,
    this.notes,
    this.envContextId,
    required this.createdBy,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['property_id'] = Variable<String>(propertyId);
    if (!nullToAbsent || zoneId != null) {
      map['zone_id'] = Variable<String>(zoneId);
    }
    if (!nullToAbsent || featureId != null) {
      map['feature_id'] = Variable<String>(featureId);
    }
    map['observed_at'] = Variable<String>(observedAt);
    map['local_tz'] = Variable<String>(localTz);
    map['lat'] = Variable<double>(lat);
    map['lng'] = Variable<double>(lng);
    if (!nullToAbsent || gpsAccuracyM != null) {
      map['gps_accuracy_m'] = Variable<double>(gpsAccuracyM);
    }
    if (!nullToAbsent || altitudeM != null) {
      map['altitude_m'] = Variable<double>(altitudeM);
    }
    if (!nullToAbsent || headingDeg != null) {
      map['heading_deg'] = Variable<double>(headingDeg);
    }
    map['observation_type'] = Variable<String>(observationType);
    if (!nullToAbsent || taxonId != null) {
      map['taxon_id'] = Variable<String>(taxonId);
    }
    if (!nullToAbsent || taxonConfidence != null) {
      map['taxon_confidence'] = Variable<String>(taxonConfidence);
    }
    if (!nullToAbsent || countEstimate != null) {
      map['count_estimate'] = Variable<int>(countEstimate);
    }
    if (!nullToAbsent || phenology != null) {
      map['phenology'] = Variable<String>(phenology);
    }
    map['is_suggestion'] = Variable<int>(isSuggestion);
    if (!nullToAbsent || acceptedAt != null) {
      map['accepted_at'] = Variable<String>(acceptedAt);
    }
    if (!nullToAbsent || acceptedBy != null) {
      map['accepted_by'] = Variable<String>(acceptedBy);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || envContextId != null) {
      map['env_context_id'] = Variable<String>(envContextId);
    }
    map['created_by'] = Variable<String>(createdBy);
    map['created_at'] = Variable<String>(createdAt);
    map['updated_at'] = Variable<String>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<String>(deletedAt);
    }
    return map;
  }

  ObservationsCompanion toCompanion(bool nullToAbsent) {
    return ObservationsCompanion(
      id: Value(id),
      propertyId: Value(propertyId),
      zoneId: zoneId == null && nullToAbsent
          ? const Value.absent()
          : Value(zoneId),
      featureId: featureId == null && nullToAbsent
          ? const Value.absent()
          : Value(featureId),
      observedAt: Value(observedAt),
