class IdentificationSuggestion extends DataClass
    implements Insertable<IdentificationSuggestion> {
  final String id;
  final String propertyId;
  final String observationId;
  final String source;
  final String? sourceDetail;

  /// model name/version, flora/project used
  final String? suggestedTaxonId;
  final String suggestedName;

  /// raw string as returned
  final double? score;

  /// 0..1
  final int? rankPosition;
  final String? reasoning;

  /// LLM re-rank rationale, shown to user
  final String? rawResponseJson;
  final String? runId;

  /// one identify() call = one run; reruns append, never mingle
  final int accepted;
  final String? createdBy;
  final String createdAt;
  final String updatedAt;
  final String? deletedAt;
  const IdentificationSuggestion({
    required this.id,
    required this.propertyId,
    required this.observationId,
    required this.source,
    this.sourceDetail,
    this.suggestedTaxonId,
    required this.suggestedName,
    this.score,
    this.rankPosition,
    this.reasoning,
    this.rawResponseJson,
    this.runId,
    required this.accepted,
    this.createdBy,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['property_id'] = Variable<String>(propertyId);
    map['observation_id'] = Variable<String>(observationId);
    map['source'] = Variable<String>(source);
    if (!nullToAbsent || sourceDetail != null) {
      map['source_detail'] = Variable<String>(sourceDetail);
    }
    if (!nullToAbsent || suggestedTaxonId != null) {
      map['suggested_taxon_id'] = Variable<String>(suggestedTaxonId);
    }
    map['suggested_name'] = Variable<String>(suggestedName);
    if (!nullToAbsent || score != null) {
      map['score'] = Variable<double>(score);
    }
    if (!nullToAbsent || rankPosition != null) {
      map['rank_position'] = Variable<int>(rankPosition);
    }
    if (!nullToAbsent || reasoning != null) {
      map['reasoning'] = Variable<String>(reasoning);
    }
    if (!nullToAbsent || rawResponseJson != null) {
      map['raw_response_json'] = Variable<String>(rawResponseJson);
    }
    if (!nullToAbsent || runId != null) {
      map['run_id'] = Variable<String>(runId);
    }
    map['accepted'] = Variable<int>(accepted);
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    map['created_at'] = Variable<String>(createdAt);
    map['updated_at'] = Variable<String>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<String>(deletedAt);
    }
    return map;
  }

  IdentificationSuggestionsCompanion toCompanion(bool nullToAbsent) {
    return IdentificationSuggestionsCompanion(
      id: Value(id),
      propertyId: Value(propertyId),
      observationId: Value(observationId),
