class PhotoPoint extends DataClass implements Insertable<PhotoPoint> {
  final String id;
  final String propertyId;
  final String? zoneId;
  final String name;
  final double lat;
  final double lng;
  final double bearingDeg;
  final double? cameraHeightCm;
  final String? subject;

  /// 'looking downstream at willow planting'
  final int? cadenceDays;

  /// reminder interval
  final String? nextDueOn;
  final String? referenceMediaId;

  /// the anchor frame for ghost overlay
  final String createdBy;
  final String createdAt;
  final String updatedAt;
  final String? deletedAt;
  const PhotoPoint({
    required this.id,
    required this.propertyId,
