  final String? zoneId;
  final double? plannedAmount;
  final double? completedAmount;
  final String? unit;

  /// 'acres','feet','each'
  final String? plannedStart;
  final String? dueOn;
  final String? completedOn;
  final String? status;
  final String? notes;
  final String createdBy;
  final String createdAt;
  final String updatedAt;
  final String? deletedAt;
